ValidationRule.errorConditionFormula:
AND(

  NOT(
    OR(
      ISPICKVAL(Status, "Draft"), 
      AND(                         
        ISPICKVAL(PRIORVALUE(Status), "Draft"),
        ISPICKVAL(Status, "Closed")
      ),
      $Permission.ByPassValidationRule, 
      ISCHANGED(ByPassValidation__c)     
    )
  )
)
